function run(mod: Mod, vector: Vector): unknown {
  try {
    const result = CALLS[vector.fn]!(mod, ...JSON.parse(JSON.stringify(vector.args)));
    return result === undefined ? { __undefined: true } : result;
  } catch (error) {
    return { __throws: String(error).slice(0, 80) };
  }
}

function sameAsExpected(vector: Vector, actual: unknown): boolean {
  const expected = vector.out as { __throws?: string };
  if (expected && typeof expected === 'object' && '__throws' in expected) return actual !== null && typeof actual === 'object' && '__throws' in (actual as object);
  return JSON.stringify(actual) === JSON.stringify(vector.out);
}

describe('요구사항 순수 코어 벡터', () => {
  it('모든 벡터가 옛 TS가 낸 값과 글자까지 같다', () => {
    vi.useFakeTimers();
    vi.setSystemTime(new Date('2026-11-10T00:00:00.000Z'));
    try {
      const failures = VECTORS.filter((vector) => !sameAsExpected(vector, run(MOD, vector))).map((vector) => `${vector.fn} ${JSON.stringify(vector.args).slice(0, 200)}`);
      expect(failures).toEqual([]);
    } finally {
      vi.useRealTimers();
    }
  });

  it('벡터가 함수마다 값이 있는 결과와 빈 결과를 둘 다 담는다', () => {
    const byFn = new Map<string, { empty: number; filled: number }>();
    for (const vector of VECTORS) {
      const slot = byFn.get(vector.fn) ?? { empty: 0, filled: 0 };
      const out = vector.out;
      const empty = out === '' || out === false || out === null || (Array.isArray(out) && out.length === 0);
      if (empty) slot.empty++;
      else slot.filled++;
      byFn.set(vector.fn, slot);
    }
    expect(byFn.size).toBe(Object.keys(CALLS).length);
    for (const [fn, slot] of byFn) expect(slot.filled, fn).toBeGreaterThan(0);
    for (const fn of ['findMentionedIds', 'extractImplementsTrailers', 'findCheckpointMentions', 'isLikelyTestFile', 'isManualStepText', 'requirementContentDrifted', 'extractPathReferences', 'verifySpecQuote', 'mentionsRequirementId', 'lintRequirement']) {
      expect(byFn.get(fn)!.empty, fn).toBeGreaterThan(0);
    }
  });

  it('옛 TS에 돌리면 의도한 차이만 실패한다', () => {
    vi.useFakeTimers();
    vi.setSystemTime(new Date('2026-11-10T00:00:00.000Z'));
    try {
      const failed = VECTORS.filter((vector) => !sameAsExpected(vector, run(old, vector)));
      expect(failed.every((vector) => vector.intended === true)).toBe(true);
      expect(failed.length).toBe(VECTORS.filter((vector) => vector.intended).length);
      expect(failed.length).toBe(5);
    } finally {
      vi.useRealTimers();
    }
  });
});
